contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.SetMinSum(0);
        c.Deposit{value: amount}();
        uint bal = c.balances(address(this));
        // Collect more than the balance: must be a no-op
        c.Collect(amount + 1);
        bool noOp = (c.balances(address(this)) == bal) && (address(c).balance == amount);
        // Collect exactly the balance: must remove it
        c.Collect(amount);
        bool ok = (c.balances(address(this)) == 0) && (address(c).balance == 0);
        assert(noOp && ok && bal == amount);
    }
    receive() external payable {}
}

