contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 deposit, uint256 amount) public payable {
        require(amount > 0);
        require(deposit >= amount);
        require(address(this).balance >= deposit);
        c.Deposit{value: deposit}();
        uint256 balBefore = c.balances(address(this));
        uint256 ethBefore = address(c).balance;
        uint256 minSum = c.MinSum();
        require(balBefore >= minSum + amount);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assert(!reverted
            && c.balances(address(this)) == balBefore - amount
            && ethBefore - address(c).balance == amount);
    }
    receive() external payable { }
}

